#pragma once

#include <string>

#include <QWidget>

// WindowDriver: lets LabCheck use your window the way a person would,
// typing into boxes and clicking buttons, with no screen at all.
// Do not edit this file.
//
// It finds each control by its object name, so the window must call
// setObjectName("CustomerBox") on its QLineEdit, and so on.
class WindowDriver
{
public:
    // Keeps the window to drive and lets it settle. It is never shown.
    explicit WindowDriver(QWidget& window);

    // Replaces the text in a QLineEdit, the same as a person typing it.
    void Type(const std::string& name, const std::string& text);

    // Clicks a QPushButton. A disabled button ignores the click, as on screen.
    void Click(const std::string& name);

    // True when the control is enabled, false when it is disabled.
    bool IsEnabled(const std::string& name);

    // The text a QLabel or QLineEdit is showing, or (blank).
    std::string Text(const std::string& name);

    // The items in a QListWidget, joined with " | ", or (empty).
    std::string Items(const std::string& name);

private:
    QWidget& window;

    // A control that does not exist yet means that part is not finished.
    template <typename T>
    T* Find(const std::string& name);

    // Lets the window finish any work the last action queued up.
    static void Flush();
};
